import org.rabochaya.projects.*;import org.w3c.dom.*;import java.util.*;import javax.xml.parsers.*;import java.io.*;
public final class ObjectListingTests {
 static int checks;static void check(boolean ok){checks++;if(!ok)throw new AssertionError("check "+checks);}
 static Element parse(String xml)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes("UTF-8"))).getDocumentElement();}
 static ObjectListing.Options opt(String q,int kind,int visibility,int sort,boolean recursive,boolean first){return new ObjectListing.Options(q,kind,visibility,sort,recursive,first);}
 static void invalid(Runnable r){boolean bad=false;try{r.run();}catch(IllegalArgumentException e){bad=true;}check(bad);}
 public static void main(String[] args)throws Exception{
  Element root=parse("<Document xmlns='http://www.opengis.net/kml/2.2' xmlns:gx='http://www.google.com/kml/ext/2.2'><Folder><name>Папка</name><visibility>0</visibility><Placemark><name>Ёлка</name><visibility>1</visibility><Point/></Placemark><Placemark><name>Маршрут</name><LineString/></Placemark><Folder><name>Вложенная</name><Placemark><name>ЕЛКА</name><Point/></Placemark></Folder></Folder><Placemark><name>Альфа</name><Point/></Placemark><Placemark><name>Бета</name><MultiGeometry><LineString/><LineString/></MultiGeometry></Placemark><Placemark><name>Смешанный</name><MultiGeometry><Point/><Polygon/></MultiGeometry></Placemark><Placemark><name>Область</name><Polygon><outerBoundaryIs><LinearRing/></outerBoundaryIs></Polygon></Placemark><Placemark><name>Трек</name><gx:Track/></Placemark><Placemark><name>Данные</name><ExtendedData><x:Point xmlns:x='urn:custom'/></ExtendedData></Placemark><GroundOverlay><name>Подложка</name></GroundOverlay><Placemark><name>Альфа</name><Point/></Placemark><Folder/></Document>");
  String token=ObjectTree.token(root);List<ObjectTree.Row> rows=ObjectTree.rows(root);ObjectListing index=ObjectListing.build(root,rows);ObjectListing.Options defaults=ObjectListing.Options.defaults();check(index.select("",defaults).size()==10);check(index.select("",opt("",0,0,0,true,false)).size()==14);
  List<ObjectListing.Item> found=index.select("",opt(" елКа ",0,0,0,true,false));check(found.size()==2);check(found.get(0).row.key.equals("0/0")&&found.get(1).row.key.equals("0/2/0"));check(found.get(1).path.equals("Корень проекта / Папка / Вложенная"));check(!found.get(0).visible&&!found.get(1).visible);
  check(index.select("",opt("елка",0,0,0,false,false)).isEmpty());check(index.select("0",opt("елка",0,0,0,false,false)).size()==1);check(index.select("0",opt("елка",0,0,0,true,false)).size()==2);check(index.select("0/2",opt("елка",0,0,0,true,false)).size()==1);check(index.select("0",opt("папка",0,0,0,true,false)).isEmpty());
  int[] counts={14,3,4,2,1,1,1,2};for(int kind=0;kind<counts.length;kind++)check(index.select("",opt("",kind,0,0,true,false)).size()==counts[kind]);
  check(index.select("",opt("",0,1,0,true,false)).size()==9);check(index.select("",opt("",0,2,0,true,false)).size()==5);check(index.select("0",opt("",0,1,0,true,false)).isEmpty());check(index.select("",opt("елка",2,2,1,true,false)).size()==2);check(index.select("",opt("елка",2,1,1,true,false)).isEmpty());
  List<ObjectListing.Item> asc=index.select("",opt("",0,0,1,false,false)),desc=index.select("",opt("",0,0,2,false,false));check(asc.get(0).row.key.equals("1")&&asc.get(1).row.key.equals("8"));check(desc.get(desc.size()-2).row.key.equals("1")&&desc.get(desc.size()-1).row.key.equals("8"));check(index.get("1").row.name.equals("Альфа"));
  List<ObjectListing.Item> first=index.select("",opt("",0,0,0,false,true));check(first.get(0).row.key.equals("0")&&first.get(1).row.key.equals("9")&&first.get(2).row.key.equals("1"));List<ObjectListing.Item> typed=index.select("",opt("",0,0,3,false,false));for(int i=1;i<typed.size();i++)check(typed.get(i-1).kind<=typed.get(i).kind);
  check(ObjectTree.token(root).equals(token));for(int i=0;i<rows.size();i++)check(ObjectTree.resolve(root,rows.get(i).key)==ObjectTree.resolve(root,index.get(rows.get(i).key).row.key));boolean immutable=false;try{asc.clear();}catch(UnsupportedOperationException e){immutable=true;}check(immutable);
  invalid(()->index.select("99",defaults));invalid(()->index.select("1",defaults));invalid(()->opt(null,0,0,0,false,false));invalid(()->opt("x",8,0,0,false,false));invalid(()->opt("x",0,3,0,false,false));invalid(()->opt("x",0,0,-1,false,false));invalid(()->opt(String.join("",Collections.nCopies(257,"x")),0,0,0,false,false));
  Element visibility=parse("<Document><visibility>0</visibility><Placemark><name>P</name><visibility>1</visibility><Point/></Placemark></Document>");check(ObjectListing.build(visibility,ObjectTree.rows(visibility)).select("",opt("",0,1,0,true,false)).isEmpty());
  Element namespaces=parse("<k:Document xmlns:k='http://www.opengis.net/kml/2.2'><k:Placemark><k:name>Étoile</k:name><k:MultiGeometry><k:Point/></k:MultiGeometry></k:Placemark></k:Document>");check(ObjectListing.build(namespaces,ObjectTree.rows(namespaces)).select("",opt("E\u0301TOILE",2,0,0,false,false)).size()==1);
  Locale previous=Locale.getDefault();try{Locale.setDefault(new Locale("tr","TR"));check(ObjectListing.normalize("POINT ЁЛКА").equals("point елка"));}finally{Locale.setDefault(previous);}
  StringBuilder many=new StringBuilder("<Document>");for(int i=0;i<12;i++)many.append("<Folder><name>Folder ").append(i).append("</name><Placemark><name>Needle</name><Point/></Placemark></Folder>");many.append("</Document>");Element numeric=parse(many.toString());ObjectListing large=ObjectListing.build(numeric,ObjectTree.rows(numeric));check(large.select("1",opt("Needle",2,0,0,true,false)).size()==1);check(large.select("1",opt("Needle",2,0,0,true,false)).get(0).row.key.equals("1/0"));
  StringBuilder deepXml=new StringBuilder("<Document>");String longName=String.join("",Collections.nCopies(1000,"Ж"));for(int i=0;i<20;i++)deepXml.append("<Folder><name>").append(longName).append("</name>");for(int i=0;i<2000;i++)deepXml.append("<Placemark><name>P").append(i).append("</name><Point/></Placemark>");for(int i=0;i<20;i++)deepXml.append("</Folder>");deepXml.append("</Document>");Element deep=parse(deepXml.toString());String deepToken=ObjectTree.token(deep);ObjectListing bounded=ObjectListing.build(deep,ObjectTree.rows(deep));List<ObjectListing.Item> nested=bounded.select("",opt("",2,0,0,true,false));check(nested.size()==2000);boolean boundedPaths=true;for(ObjectListing.Item item:nested)boundedPaths&=item.path.length()<=256;check(boundedPaths);check(ObjectTree.token(deep).equals(deepToken));
  Element notes=parse("<Document xmlns='http://www.opengis.net/kml/2.2' xmlns:x='urn:foreign'><Folder><name>Folder</name><description>Parent note</description><Placemark><name>Ёлка</name><description><![CDATA[На <b>СЕВЕРЕ</b>&nbsp;реки<p>Рубеж &#x401;ж &amp; мост</p><a href='https://private.invalid/url-secret'>Ссылка</a><img src='attachments/secret.jpg' alt='attr-secret'><script>script-secret</script><style>style-secret</style><!--comment-secret-->]]></description><Point/></Placemark></Folder><Placemark><name>Север</name><description>Other</description><Point/></Placemark><Placemark><name>Other</name><x:description>Foreign secret</x:description><Point/></Placemark><Placemark><name>Other 2</name><ExtendedData><description>Nested secret</description></ExtendedData><Point/></Placemark></Document>");
  String noteToken=ObjectTree.token(notes);ObjectListing noteIndex=ObjectListing.build(notes,ObjectTree.rows(notes));
  check(noteIndex.select("",new ObjectListing.Options("север",0,0,0,true,false,0)).size()==1);
  check(noteIndex.select("",new ObjectListing.Options("север",0,0,0,true,false,1)).get(0).row.key.equals("0/0"));
  check(noteIndex.select("",new ObjectListing.Options("север",0,0,0,true,false,2)).size()==2);
  for(String q:new String[]{"На севере реки","рубеж еж & мост","Ссылка"})check(noteIndex.select("",new ObjectListing.Options(q,0,0,0,true,false,1)).size()==1);
  for(String q:new String[]{"url-secret","secret.jpg","attr-secret","script-secret","style-secret","comment-secret","Foreign secret","Nested secret","Елка на"})check(noteIndex.select("",new ObjectListing.Options(q,0,0,0,true,false,2)).isEmpty());
  check(noteIndex.select("",new ObjectListing.Options("parent note",0,0,0,true,false,1)).size()==1);
  check(noteIndex.select("0",new ObjectListing.Options("parent note",0,0,0,true,false,1)).isEmpty());
  check(noteIndex.select("",new ObjectListing.Options("",0,0,0,true,false,1)).size()==5);
  check(noteIndex.select("",ObjectListing.Options.defaults()).size()==4);
  check(noteToken.equals(ObjectTree.token(notes)));
  invalid(()->new ObjectListing.Options("",0,0,0,false,false,-1));invalid(()->new ObjectListing.Options("",0,0,0,false,false,3));
  check(ObjectListing.descriptionText("A<b title='>'>B</b><br>C").equals("AB C"));
  check(ObjectListing.descriptionText("2 < 3 &amp; 4 > 1").equals("2 < 3 & 4 > 1"));
  check(ObjectListing.descriptionText("&#128512; &#x1F600; &#0; &#xD800; &#1114112; &#-1; &#xZZ;").equals("😀 😀 &#0; &#xD800; &#1114112; &#-1; &#xZZ;"));
  check(ObjectListing.descriptionText("&lt;b&gt;A&lt;/b&gt; &amp;lt; &unknown;").equals("<b>A</b> &lt; &unknown;"));
  check(ObjectListing.descriptionText("A<!--unfinished").equals("A"));
  check(ObjectListing.descriptionText("A<SCRIPT src='url'>hidden</ScRiPt>B<style>hidden</style>C").equals("ABC"));
  check(ObjectListing.descriptionText("A<template>hidden<template>inner</template>outer</template>B").equals("AB"));
  check(ObjectListing.descriptionText("A<b unfinished").equals("A<b unfinished"));
  String ampersands=String.join("",Collections.nCopies(200000,"&"));check(ObjectListing.descriptionText(ampersands).equals(ampersands));
  String longDescription=String.join("",Collections.nCopies(20000,"абв "))+"дальний рубеж";Element longNotes=parse("<Document><Placemark><name>Long</name><description>"+longDescription+"</description><Point/></Placemark></Document>");check(ObjectListing.build(longNotes,ObjectTree.rows(longNotes)).select("",new ObjectListing.Options("дальний рубеж",0,0,0,false,false,1)).size()==1);
  System.out.println("PASS ObjectListing: "+checks+" assertions");
 }
}
